package org.eurorig.app;

import android.app.*;
import android.content.*;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import org.json.*;
import org.eurorig.routing.*;

/** Search and route editing share the installed map and the existing audited router. */
final class JourneyUi {
    final MainActivity host;private Dialog dialog;EditText query;ListView results;
    /** Icon per shortcut, in the same order as the shortcut names. */
    private static final int[] SHORTCUT_ICONS={R.drawable.ic_shortcut_favourites,R.drawable.ic_shortcut_fuel,R.drawable.ic_shortcut_parking,R.drawable.ic_shortcut_services};
    private final Handler handler=new Handler(Looper.getMainLooper());private int generation;
    private int bg,panel,text,muted,accent;
    JourneyUi(MainActivity host){this.host=host;}
    private int dp(float v){return Math.round(v*host.getResources().getDisplayMetrics().density);}
    private void colors(){boolean dark=host.getSharedPreferences("settings",0).getBoolean("dark_mode",false);bg=dark?0xff000000:0xfffff9f0;panel=dark?0xff211c17:0xffeee4d7;text=dark?0xfff6efe5:0xff2c2118;muted=dark?0xffc0af9b:0xff6b5948;accent=dark?0xffe89045:0xff9c3708;}
    private GradientDrawable surface(){GradientDrawable d=new GradientDrawable();d.setColor(panel);d.setCornerRadius(dp(18));return d;}
    private TextView label(String s,int size,int color){TextView t=new TextView(host);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
    private Button button(String s,Runnable click){Button v=new Button(host);v.setText(s);v.setAllCaps(false);v.setTextSize(16);v.setTextColor(accent);v.setBackground(surface());v.setMinHeight(dp(52));v.setOnClickListener(x->click.run());return v;}
    /** Borderless glyph, so back and clear can sit inside the search bar rather than above it. */
    private TextView glyph(String symbol,String description,Runnable click){TextView v=new TextView(host);v.setText(symbol);v.setTextSize(27);v.setTextColor(accent);v.setGravity(Gravity.CENTER);v.setContentDescription(description);v.setOnClickListener(x->click.run());return v;}
    private LinearLayout column(){LinearLayout v=new LinearLayout(host);v.setOrientation(LinearLayout.VERTICAL);return v;}
    private LinearLayout page(String title){return page(title,true);}
    /** Pages whose back control sits inside their own bar do not need a separate header row. */
    private LinearLayout page(String title,boolean header){close();host.overlayOpened();colors();dialog=new Dialog(host);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout root=column();root.setBackgroundColor(bg);root.setPadding(dp(16),dp(12),dp(16),dp(12));if(header){LinearLayout head=new LinearLayout(host);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(button("‹",this::close),new LinearLayout.LayoutParams(dp(48),dp(52)));TextView name=label(title,25,text);name.setTypeface(null,Typeface.BOLD);name.setPadding(dp(12),0,0,0);head.addView(name,new LinearLayout.LayoutParams(0,-2,1));root.addView(head);}dialog.setContentView(root);dialog.show();Window w=dialog.getWindow();w.clearFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);w.addFlags(WindowManager.LayoutParams.FLAG_DRAWS_SYSTEM_BAR_BACKGROUNDS);w.setBackgroundDrawableResource(android.R.color.transparent);w.setStatusBarColor(bg);w.setNavigationBarColor(bg);w.getDecorView().setSystemUiVisibility(bg==0xff000000?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);w.setLayout(-1,-1);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);return root;}
    void close(){generation++;handler.removeCallbacksAndMessages(null);if(dialog!=null)dialog.dismiss();dialog=null;}
    boolean showing(){return dialog!=null&&dialog.isShowing();}
    private void row(LinearLayout parent,String title,String detail,Runnable action){LinearLayout box=column();box.setPadding(dp(16),dp(14),dp(16),dp(14));box.setBackground(surface());TextView name=label(title,18,text);name.setTypeface(null,Typeface.BOLD);box.addView(name);if(!detail.isEmpty()){TextView sub=label(detail,14,muted);sub.setPadding(0,dp(5),0,0);box.addView(sub);}box.setMinimumHeight(dp(72));box.setFocusable(true);box.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);parent.addView(box,p);}
    void edit(){
        LinearLayout root=page("Edit route");boolean wide=host.getResources().getConfiguration().screenWidthDp>host.getResources().getConfiguration().screenHeightDp;
        LinearLayout split=new LinearLayout(host);split.setOrientation(wide?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);root.addView(split,new LinearLayout.LayoutParams(-1,0,1));LinearLayout summary=column(),fields=column();summary.setPadding(dp(4),dp(12),dp(20),dp(12));ScrollView scroll=new ScrollView(host);scroll.addView(fields);if(wide){split.addView(summary,new LinearLayout.LayoutParams(0,-1,.8f));split.addView(scroll,new LinearLayout.LayoutParams(0,-1,1.2f));}else{split.addView(summary);split.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
        Router.Route route=Store.route;LinearLayout metrics=new LinearLayout(host);String[] names={"ARRIVAL","DURATION","DISTANCE"};String[] values=route==null?new String[]{"—","—","—"}:new String[]{java.text.DateFormat.getTimeInstance(java.text.DateFormat.SHORT).format(new Date(System.currentTimeMillis()+(long)(route.seconds*1000))),duration(route.seconds),NavigationDistance.format(route.metres)};
        for(int i=0;i<3;i++){LinearLayout metric=column();metric.setPadding(dp(4),dp(8),dp(4),dp(12));metric.addView(label(names[i],11,muted));metric.addView(label(values[i],19,accent));metrics.addView(metric,new LinearLayout.LayoutParams(0,-2,1));}summary.addView(metrics);
        row(fields,"◉  "+(Store.originChosen?host.pointLabel(Store.start):"Choose starting point"),"Starting point",()->search(1));
        for(int i=0;i<Store.viaPoints.size();i++){final int at=i;Graph.Node p=Store.viaPoints.get(i);row(fields,"•  "+(p.label.isEmpty()?String.format(Locale.ROOT,"%.6f, %.6f",p.lat,p.lon):p.label),"Waypoint "+(i+1)+" · tap to move or remove",()->new AlertDialog.Builder(host).setTitle("Waypoint "+(at+1)).setItems(new String[]{"Move earlier","Move later","Remove"},(d,w)->{if(w==2)Store.viaPoints.remove(at);else{int other=at+(w==0?-1:1);if(other>=0&&other<Store.viaPoints.size())Collections.swap(Store.viaPoints,at,other);}host.routePointsChanged();edit();}).show());}
        row(fields,"＋  Add waypoint","Route through another location",()->{if(Store.viaPoints.size()>=5){host.error("Up to five waypoints can be added.");return;}search(2);});
        row(fields,"⚑  "+(Store.destinationChosen?host.pointLabel(Store.end):"Choose destination"),"Destination",()->search(0));
        Button swap=button("Swap start and destination",()->{int a=Store.start;Store.start=Store.end;Store.end=a;boolean chosen=Store.originChosen;Store.originChosen=Store.destinationChosen;Store.destinationChosen=chosen;Collections.reverse(Store.viaPoints);Store.revokeAuthorisation();host.routePointsChanged();edit();});fields.addView(swap);
        summary.addView(button("Use current location",()->{close();host.useGpsOrigin();}));summary.addView(button("Vehicle profile",()->{close();host.openTrucks();}));summary.addView(button("Route options",host::openRoutingOptions));
        Button calculate=button("Calculate route",()->{close();host.planSelectedRoute();});calculate.setEnabled(Store.originChosen&&Store.destinationChosen);root.addView(calculate,new LinearLayout.LayoutParams(-1,dp(56)));
    }
    static double[] coordinates(String value){String[] pieces=value.trim().split(",",-1);if(pieces.length!=2)throw new IllegalArgumentException("Use latitude, longitude.");double lat=Double.parseDouble(pieces[0].trim()),lon=Double.parseDouble(pieces[1].trim());if(!Double.isFinite(lat)||!Double.isFinite(lon)||Math.abs(lat)>85||Math.abs(lon)>180)throw new IllegalArgumentException("Coordinates are outside the map's latitude/longitude range.");return new double[]{lat,lon};}
    void search(int target){
        LinearLayout root=page(target==1?"Starting point":target==2?"Add waypoint":"Search",false);final Dialog shown=dialog;
        LinearLayout bar=new LinearLayout(host);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setBackground(surface());bar.setPadding(dp(2),0,dp(2),0);query=new EditText(host);query.setSingleLine(true);query.setBackground(null);query.setTextSize(19);query.setTextColor(text);query.setHintTextColor(muted);query.setHint("Address, place or latitude, longitude");query.setContentDescription("Search address or coordinates");query.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH|android.view.inputmethod.EditorInfo.IME_FLAG_NO_EXTRACT_UI);bar.addView(glyph("‹","Close search",this::close),new LinearLayout.LayoutParams(dp(40),dp(52)));bar.addView(query,new LinearLayout.LayoutParams(0,dp(60),1));bar.addView(glyph("×","Clear search",()->query.setText("")),new LinearLayout.LayoutParams(dp(40),dp(52)));root.addView(bar);
        LinearLayout shortcuts=new LinearLayout(host);String[] names={"Favourites","Fuel","Parking","Services"};String[] kinds={"","fuel","parking","car_repair"};ArrayList<Graph.Node> points=new ArrayList<>();TextView status=label("Recent searches",14,muted);status.setPadding(dp(8),dp(14),0,dp(8));
        ArrayAdapter<Graph.Node> adapter=new ArrayAdapter<Graph.Node>(host,android.R.layout.simple_list_item_2,android.R.id.text1,points){public View getView(int position,View convert,android.view.ViewGroup parent){View v=super.getView(position,convert,parent);Graph.Node p=getItem(position);TextView title=v.findViewById(android.R.id.text1),sub=v.findViewById(android.R.id.text2);title.setText(p.label.isEmpty()?"Coordinates":p.label);title.setTextColor(text);title.setTextSize(18);sub.setTextColor(muted);sub.setText(String.format(Locale.ROOT,"%.8f, %.8f",p.lat,p.lon));v.setMinimumHeight(dp(78));return v;}};
        for(int i=0;i<names.length;i++){final int at=i;Runnable action=()->{if(at==0){close();host.favourites();return;}int token=++generation;status.setText("Nearby "+names[at].toLowerCase(Locale.ROOT));double lat=Double.isFinite(Store.lat)?Store.lat:Store.graph.nodes[Store.start].lat,lon=Double.isFinite(Store.lon)?Store.lon:Store.graph.nodes[Store.start].lon;Store.mapWorker.execute(()->{List<Graph.Node> found=Store.display==null?Collections.emptyList():Store.display.nearby(kinds[at],lat,lon);handler.post(()->{if(token!=generation||!shown.isShowing())return;points.clear();points.addAll(found);adapter.notifyDataSetChanged();status.setText(found.isEmpty()?"No mapped places in this area":"Nearby "+names[at].toLowerCase(Locale.ROOT));});});};
            LinearLayout tile=column();tile.setGravity(Gravity.CENTER);tile.setBackground(surface());tile.setFocusable(true);tile.setContentDescription(names[i]);tile.setOnClickListener(v->action.run());
            ImageView icon=new ImageView(host);icon.setImageResource(SHORTCUT_ICONS[i]);icon.setColorFilter(accent);icon.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
            tile.addView(icon,new LinearLayout.LayoutParams(dp(26),dp(26)));
            TextView caption=label(names[i],11,muted);caption.setGravity(Gravity.CENTER);tile.addView(caption);
            LinearLayout.LayoutParams tileSize=new LinearLayout.LayoutParams(0,dp(66),1);tileSize.rightMargin=dp(6);shortcuts.addView(tile,tileSize);}
        LinearLayout.LayoutParams shortcutRow=new LinearLayout.LayoutParams(-1,-2);shortcutRow.topMargin=dp(8);root.addView(shortcuts,shortcutRow);root.addView(status);results=new ListView(host);results.setAdapter(adapter);root.addView(results,new LinearLayout.LayoutParams(-1,0,1));
        Runnable recent=()->{points.clear();try{JSONArray a=new JSONArray(host.getSharedPreferences("search_history",0).getString("places","[]"));for(int i=0;i<a.length();i++){JSONObject p=a.getJSONObject(i);points.add(new Graph.Node(p.getDouble("lat"),p.getDouble("lon"),p.getString("name")));}}catch(JSONException ignored){}adapter.notifyDataSetChanged();status.setText(points.isEmpty()?"Search mapped addresses, places or coordinates":"Recent searches");};recent.run();
        query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){int token=++generation;handler.removeCallbacksAndMessages(null);points.clear();adapter.notifyDataSetChanged();String raw=s.toString().trim();if(raw.isEmpty()){recent.run();return;}if(raw.indexOf(',')>=0&&raw.matches("[+\\-0-9.,\\s]+")){try{double[] c=coordinates(raw);points.add(new Graph.Node(c[0],c[1],raw));adapter.notifyDataSetChanged();status.setText("View this coordinate on the map");}catch(IllegalArgumentException e){status.setText("Enter valid latitude, longitude");}return;}if(raw.length()<2){status.setText("Type at least two characters");return;}status.setText("Searching installed map…");DisplayDatabase display=Store.display;Graph graph=Store.graph;handler.postDelayed(()->Store.mapWorker.execute(()->{try{List<Graph.Node> found=new ArrayList<>();if(display!=null)found.addAll(display.search(raw));else for(int id:graph.search(raw))found.add(graph.nodes[id]);handler.post(()->{if(token!=generation||!shown.isShowing())return;points.clear();points.addAll(found);adapter.notifyDataSetChanged();status.setText(found.isEmpty()?"No mapped address found. Try a street, city or coordinates.":found.size()+" mapped places");});}catch(RuntimeException error){handler.post(()->{if(token==generation&&shown.isShowing())status.setText("Search unavailable. Try again.");});}}),250);}});
        results.setOnItemClickListener((parent,v,position,id)->{if(position>=points.size())return;Graph.Node p=points.get(position);remember(p);host.getSystemService(android.view.inputmethod.InputMethodManager.class).hideSoftInputFromWindow(query.getWindowToken(),0);close();if(target==0)host.previewPlace(p);else{host.chooseJourneyPoint(p,target);edit();}});
        query.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH&&points.size()==1){results.performItemClick(results.getChildAt(0),0,0);return true;}return false;});query.requestFocus();
        shown.setOnDismissListener(d->{generation++;handler.removeCallbacksAndMessages(null);});
    }
    private void remember(Graph.Node point){try{JSONArray old=new JSONArray(host.getSharedPreferences("search_history",0).getString("places","[]")),recent=new JSONArray();recent.put(new JSONObject().put("lat",point.lat).put("lon",point.lon).put("name",point.label));for(int i=0;i<old.length()&&recent.length()<15;i++){JSONObject item=old.getJSONObject(i);if(Math.abs(item.getDouble("lat")-point.lat)>.00000001||Math.abs(item.getDouble("lon")-point.lon)>.00000001)recent.put(item);}host.getSharedPreferences("search_history",0).edit().putString("places",recent.toString()).apply();}catch(JSONException ignored){}}
    private static String duration(double s){long m=Math.max(1,Math.round(s/60));return m<60?m+" min":m/60+" h "+m%60+" min";}
}
